    33→    const block = chain.forkChoice.getBlockHex(blockRootHex);
    34→    // If the block is not in fork choice, it may be finalized. Attempt to find its slot in block archive
    35→    const slot = block ? block.slot : await db.blockArchive.getSlotByRoot(blockRoot);
    36→
    37→    if (slot === null) {
