    45→    // If any root in the request content references a block earlier than minimum_request_epoch, peers MAY respond with
    46→    // error code 3: ResourceUnavailable or not include the data column sidecar in the response.
    47→    // https://github.com/ethereum/consensus-specs/blob/v1.6.0-alpha.5/specs/fulu/p2p-interface.md#datacolumnsidecarsbyroot-v1
